content:
{
  "promos": [
    {
      "title": "The Witch Will Be Dead",
      "start_block": "B012",
      "end_block": "B038",
      "hook": "Lady Harrington's cruel, taunting line: \"Imagine Juliana seeing this,\" followed by Lord Harrington's sinister reply: \"She won't be seeing anything for long.\"",
      "cliffhanger": "The elder nobleman's deadly, uncompromising declaration: \"And its witch will be dead,\" as a cold smile spreads across his face.",
      "why": "Opens on a chilling threat against an unseen victim, builds dread through the conspirators' gloating, and cuts on the execution promise before any rescue appears.",
      "context_gap": "A stranger would not know who Juliana is or why she is called a witch, but the threat is clear enough to hook."
    },
    {
      "title": "Every Exit Is Sealed",
      "start_block": "B026",
      "end_block": "B050",
      "hook": "The Blond Nobleman's nervous, determined line: \"Everything must go perfectly,\" as Rupert stands at the altar in his ornate black coat.",
      "cliffhanger": "Catherine's smug, coquettish line: \"And you look better in silk than you ever did as an ignored cousin,\" as the couple exchange triumphant smiles.",
      "why": "Starts on wedding tension, reveals the sealed exits and execution plot, then ends on the villains' vanity right before the ceremony completes.",
      "context_gap": "A stranger would not know Rupert is a usurper or that Alexander is coming, but the sinister atmosphere carries the promo."
    },
    {
      "title": "A Queen Walks to Ruin",
      "start_block": "B039",
      "end_block": "B051",
      "hook": "The massive cathedral doors swing open with swelling organ music, flooding the aisle with golden light as Catherine appears silhouetted in her imperial bridal gown.",
      "cliffhanger": "Rupert and Catherine exchange conspiratorial, triumphant smiles at the altar as the solemn organ chord holds and the scene cuts to black.",
      "why": "A visually stunning bride entrance that feels like a coronation, but the conspiratorial smiles and the cut to black leave the wedding unresolved.",
      "context_gap": "A stranger would not know this wedding is built on treason and that Alexander's retribution is already at the gates."
    }
  ],
  "moments": [
    {
      "start_block": "B012",
      "end_block": "B016",
      "kind": "hook",
      "description": "Lady Harrington taunts that Juliana will see the wedding, and Lord Harrington coldly replies she won't be seeing anything for long, then scoffs that the place has always been unlucky for Juliana."
    },
    {
      "start_block": "B032",
      "end_block": "B038",
      "kind": "cliffhanger",
      "description": "The elder nobleman confirms all entrances are covered, vows Ashburgh will have its new Duke and Duchess by sunset, and declares the witch will be dead."
    },
    {
      "start_block": "B039",
      "end_block": "B045",
      "kind": "reveal",
      "description": "Cathedral doors open to blinding golden light as Catherine appears in a breathtaking cream and gold imperial bridal gown, and Lady Harrington whispers she looks like a queen."
    },
    {
      "start_block": "B047",
      "end_block": "B051",
      "kind": "cliffhanger",
      "description": "Rupert takes Catherine's hands at the altar, she mocks him as an ignored cousin, and they exchange triumphant smiles as the scene cuts to black."
    }
  ]
}
